import { BaseAgent } from "../server/agent-builder/agent.ts";
import { CLITool } from "../server/tools/implementations/cli-tool.ts";


export class TestCLIBotAgent extends BaseAgent {
  constructor() {
    super({
      name: "Test CLI Bot",
      description: "Test CLI agent with new template",
      version: "1.0",
      systemPrompt: "You are a system administration assistant.",
      tools: [
  "cli-tool"
],
      inputSchema: {
  "command": {
    "type": "string",
    "required": true,
    "description": "Shell command to execute"
  }
},
      outputSchema: {},
      dependencies: [],
      environmentVars: [],
      timeout: 0,
      retries: 0,
      memory: false
    });
  }

  protected async execute(input: Record<string, any>): Promise<any> {
    this.log("Starting execution with input:", input);
    
    try {
      // Your custom agent logic goes here
      // Access input fields: input.command
      
            // Process based on selected tools: cli-tool
      // CLI Tool integration - execute shell commands
      let cliResults = [];
      if (input.command || input.commands) {
        const commands = Array.isArray(input.commands) ? input.commands : [input.command].filter(Boolean);
        
        for (const cmd of commands) {
          try {
            if (typeof cmd === 'string') {
              const [command, ...args] = cmd.split(' ');
              const result = await CLITool.executeCommand(command, args);
              cliResults.push({ command: cmd, ...result });
              this.log(`Executed: ${cmd}`, result.success ? '✅' : '❌');
            }
          } catch (error: any) {
            this.error("CLI command failed:", error.message);
            cliResults.push({ command: cmd, success: false, error: error.message });
          }
        }
      }

      // Generate CLI task summary
      const successfulCommands = cliResults.filter(r => r.success);
      const taskSummary = `Executed ${cliResults.length} commands, ${successfulCommands.length} successful. Working directory: ${process.cwd()}`;


      
      // Return structured output matching your output schema
      const result = {
        task_completed: cliResults.length > 0 ? `Executed ${cliResults.length} shell commands` : "No commands executed",
        commands_executed: cliResults.map(r => r.command) || [],
        results: cliResults || [],
        summary: taskSummary || "Task completed",
        
        timestamp: new Date().toISOString(),
        agent: this.config.name
      };
      
      this.log("Execution completed successfully:", result);
      return result;
      
    } catch (error: any) {
      this.error("Execution failed:", error);
      throw error;
    }
  }
}

// Default export for Agent-Lab runner compatibility
export default async function run(args: string[]) {
  const agent = new TestCLIBotAgent();
  return await agent.run(args);
}
